import sys, json

def deleteDuplicates(head_arr):
    if not head_arr: return []
    res = []
    i = 0
    while i < len(head_arr):
        if i + 1 < len(head_arr) and head_arr[i] == head_arr[i+1]:
            val = head_arr[i]
            while i < len(head_arr) and head_arr[i] == val:
                i += 1
        else:
            res.append(head_arr[i])
            i += 1
    return res

if __name__ == '__main__':
    data = sys.stdin.read().strip()
    if data:
        head_arr = json.loads(data)
        print(json.dumps(deleteDuplicates(head_arr)))
    else:
        print("[]")

