vector<int> deleteDuplicates(vector<int>& nums) {
    vector<int> res;
    int n = nums.size();
    for (int i = 0; i < n; i++) {
        if (i + 1 < n && nums[i] == nums[i+1]) {
            int val = nums[i];
            while (i < n && nums[i] == val) i++;
            i--;
        } else {
            res.push_back(nums[i]);
        }
    }
    return res;
